INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-05-s0-2', 'exam-linear-algebra-set-05', 'exam-linear-algebra-set-05-sec-0', 0, '设A,B均为n阶方阵,下列结论', '设 A, B 均为 n 阶方阵, 下列结论正确的是( )', '["若 AB = O, 则 A = O 或 B = O","若 AB = E, 则 $\\\\left|A\\\\right| \\\\neq 0$ 且 $\\\\left|B\\\\right| \\\\neq 0$","$(A+B)^{2}=A^{2}+2AB+B^{2}$","$(A+B)(A-B)=A^{2}-B^{2}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第05套', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-05-s0-3', 'exam-linear-algebra-set-05', 'exam-linear-algebra-set-05-sec-0', 0, '设A,B均为n阶方阵,下列结论', '设 A, B 均为 n 阶方阵, 下列结论正确的是( )', '["$(AB)^{T} = A^{T} B^{T}$","$AA^{T} = A^{T} A$","若 $A^{T} = A$ , 则 $(A^{2})^{T} = A^{2}$","若 $A^{T} = A, B^{T} = B$ , 则 $(AB)^{T} = AB$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第05套', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
